# ============================================================================= # SpotifyDL v2 — Windows PowerShell Full Deploy Script # # Usage: #   $env:GITHUB_TOKEN = 'ghp_xxxxxxxx' #   .scripts/full-deploy.ps1 # ============================================================================= param( [string]$GithubUser = '', [string]$RepoName = 'spotifydl-v2', [string]$AppName = 'spotifydl-v2' ) # Colors $Red = 'Red' $Green = 'Green' $Blue = 'Cyan' $Yellow = 'Yellow' # Banner Write-Host '' Write-Host '╔═══════════════════════════════════════════════════════════════╗' -ForegroundColor $Blue Write-Host '║ 🎵 SpotifyDL v2 — FULL DEPLOY (Windows) ║' -ForegroundColor $Blue Write-Host '╚═══════════════════════════════════════════════════════════════╝' -ForegroundColor $Blue Write-Host '' # Check prerequisites Write-Host '🔍 Checking prerequisites...' -ForegroundColor $Blue $checks = @() # Check git if (Get-Command git -ErrorAction SilentlyContinue) { $checks += '✅ git' } else { $checks += '❌ git (install from https://git-scm.com)' } } # Check node if (Get-Command node -ErrorAction SilentlyContinue) { $checks += '✅ node' } else { $checks += '❌ node (install from https://nodejs.org)' } } # Check npm if (Get-Command npm -ErrorAction SilentlyContinue) { $checks += '✅ npm' } else { $checks += '❌ npm' } } # Check flyctl if (Get-Command flyctl -ErrorAction SilentlyContinue) { $checks += '✅ flyctl' } else { $checks += '⚠️ flyctl (install from https://fly.io/docs/hands-on/install-flyctl/)' } } # Check docker if (Get-Command docker -ErrorAction SilentlyContinue) { $checks += '✅ docker' } else { $checks += '⚠️ docker (optional, for local testing)' } } foreach ($check in $checks) { Write-Host ('  ' + $check) } # Check if in repo if (-not (Test-Path '.git')) { Write-Host '❌ Not a git repository!' -ForegroundColor $Red exit 1 } # Get GitHub user if not provided if (-not $GithubUser) { if (Test-Path '.github-config') { $config = Get-Content '.github-config' | ConvertFrom-StringData $GithubUser = $config.GITHUB_USER Write-Host ('📝 Using GitHub user from config: ' + $GithubUser) -ForegroundColor $Blue } else { $GithubUser = Read-Host 'Enter your GitHub username' } } # Step 1: Git operations Write-Host '' Write-Host '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━' -ForegroundColor $Blue Write-Host 'STEP 1: Git Commit & Push' -ForegroundColor $Blue Write-Host '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━' -ForegroundColor $Blue # Set remote $remoteUrl = 'https://github.com/' + $GithubUser + '/' + $RepoName + '.git' $existingRemote = git remote get-url origin 2>$null if ($existingRemote) { git remote set-url origin $remoteUrl Write-Host ('📝 Remote updated: ' + $remoteUrl) -ForegroundColor $Blue } else { git remote add origin $remoteUrl Write-Host ('📝 Remote added: ' + $remoteUrl) -ForegroundColor $Blue } # Commit git add -A $status = git status --short if ($status) { $msg = Read-Host 'Enter commit message [Auto-deploy]' if (-not $msg) { $msg = 'Auto-deploy' } git commit -m $msg Write-Host '✅ Committed' -ForegroundColor $Green } else { Write-Host '⚠️ No changes' -ForegroundColor $Yellow } # Push Write-Host '📤 Pushing to GitHub...' -ForegroundColor $Blue git push -u origin main Write-Host '✅ Pushed!' -ForegroundColor $Green # Step 2: Fly.io Deploy Write-Host '' Write-Host '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━' -ForegroundColor $Blue Write-Host 'STEP 2: Deploy to Fly.io (Primary)' -ForegroundColor $Blue Write-Host '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━' -ForegroundColor $Blue $flyExists = Get-Command flyctl -ErrorAction SilentlyContinue if (-not $flyExists) { Write-Host '❌ flyctl not found!' -ForegroundColor $Red Write-Host 'Install: https://fly.io/docs/hands-on/install-flyctl/' -ForegroundColor $Yellow } else { # Check login try { $flyUser = flyctl auth whoami 2>$null if ($flyUser) { Write-Host ('✅ Logged in as: ' + $flyUser) -ForegroundColor $Green } else { Write-Host '🔐 Please login: flyctl auth login' -ForegroundColor $Yellow exit 1 } } catch { Write-Host '🔐 Please login: flyctl auth login' -ForegroundColor $Yellow exit 1 } # Check/create app $apps = flyctl apps list 2>$null | Select-String $AppName if (-not $apps) { Write-Host '📦 Creating app...' -ForegroundColor $Blue flyctl launch --name $AppName --region fra --dockerfile Dockerfile --no-deploy } else { Write-Host '✅ App exists' -ForegroundColor $Green } # Check/create volume $volumes = flyctl volumes list --app $AppName 2>$null | Select-String 'spotifydl_data' if (-not $volumes) { Write-Host '💾 Creating volume...' -ForegroundColor $Blue flyctl volumes create spotifydl_data --size 3 --region fra --app $AppName } else { Write-Host '✅ Volume exists' -ForegroundColor $Green } # Set secrets from .env if exists if (Test-Path '.env') { Write-Host '🔑 Setting secrets from .env...' -ForegroundColor $Blue $envContent = Get-Content '.env' foreach ($line in $envContent) { if ($line -match '^#') { continue } if ($line -match '^s') { continue } $parts = $line -split '=', 2 $key = $parts[0].Trim() $value = $parts[1].Trim() # Skip template values if ($value -match 'your_|YOUR_|changeme') { continue } if (-not $value) { continue } Write-Host ('  Setting: ' + $key) -ForegroundColor $Cyan flyctl secrets set ($key + '=' + $value) --app $AppName 2>$null } Write-Host '✅ Secrets set' -ForegroundColor $Green } # Deploy Write-Host '🚢 Deploying...' -ForegroundColor $Blue flyctl deploy --app $AppName Write-Host '✅ Deployed!' -ForegroundColor $Green # Status Write-Host '' Write-Host '📊 Status:' -ForegroundColor $Blue flyctl status --app $AppName } # Step 3: Render Deploy Write-Host '' Write-Host '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━' -ForegroundColor $Blue Write-Host 'STEP 3: Deploy to Render (Mirror)' -ForegroundColor $Blue Write-Host '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━' -ForegroundColor $Blue if ($env:RENDER_API_KEY -and $env:RENDER_SERVICE_ID) { try { Invoke-RestMethod -Uri ('https://api.render.com/v1/services/' + $env:RENDER_SERVICE_ID + '/deploys') -Method Post -Headers @{ Authorization = 'Bearer ' + $env:RENDER_API_KEY; 'Content-Type' = 'application/json' } -Body '{clearCache: true}' Write-Host '✅ Render deploy triggered!' -ForegroundColor $Green } catch { Write-Host ('⚠️ Render failed: ' + $_.Exception.Message) -ForegroundColor $Yellow } } else { Write-Host '⚠️ Skipping Render (set RENDER_API_KEY and RENDER_SERVICE_ID)' -ForegroundColor $Yellow } # Step 4: DNS Info Write-Host '' Write-Host '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━' -ForegroundColor $Blue Write-Host 'STEP 4: DNS Configuration' -ForegroundColor $Blue Write-Host '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━' -ForegroundColor $Blue if (Get-Command flyctl -ErrorAction SilentlyContinue) { Write-Host '📋 Get your Fly.io IPs for DNS:' -ForegroundColor $Yellow Write-Host ('  flyctl ips list --app ' + $AppName) -ForegroundColor $Cyan Write-Host '' Write-Host 'Add these DNS records for dyrakarmy.eu:' -ForegroundColor $Yellow Write-Host '  Type A     @   → YOUR_IPV4' -ForegroundColor $Cyan Write-Host '  Type AAAA  @   → YOUR_IPV6' -ForegroundColor $Cyan Write-Host '  Type CNAME www → ' + $AppName + '.fly.dev' -ForegroundColor $Cyan } # Final Write-Host '' Write-Host '╔═══════════════════════════════════════════════════════════════╗' -ForegroundColor $Green Write-Host '║ ✅ ALL DONE! ║' -ForegroundColor $Green Write-Host '╚═══════════════════════════════════════════════════════════════╝' -ForegroundColor $Green Write-Host '' Write-Host ('🌐 Primary:  https://' + $AppName + '.fly.dev') -ForegroundColor $Green Write-Host '🌐 Mirror:   Check https://dashboard.render.com' -ForegroundColor $Green Write-Host '' Write-Host 'Useful commands:' -ForegroundColor $Yellow Write-Host ('  flyctl logs --app ' + $AppName) -ForegroundColor $Cyan Write-Host ('  flyctl status --app ' + $AppName) -ForegroundColor $Cyan Write-Host '  git log --oneline' -ForegroundColor $Cyan